// Package telemetry forwards testkit's telemetry-service domain (P6) to the
// embedded telemetry-service module. Messages mirror the downstream proto 1:1,
// so every converter below is a field-identical copy (enums int-cast,
// sub-messages recursive). Regenerated by /tmp/gen_forward.py.
package telemetry

import (
	"context"
	telemetryv1 "github.com/servekit/api/gen/go/telemetry/v1"

	dnv1 "github.com/servekit/api/gen/go/telemetry/v1"
	testkitv1 "github.com/servekit/api/gen/go/testkit/v1"
	telemetryservice "github.com/servekit/telemetry-service/pkg"
	"google.golang.org/grpc/metadata"
)

// Service holds the telemetry-service client (module or grpc mode — the
// pkg.Service interface covers both).
type Service struct {
	client telemetryservice.Service
	// adminToken is forwarded as `Authorization: Bearer <token>`
	// metadata on admin-surface RPCs (telemetry-service guards them;
	// license-service has no guard today — empty token is a no-op).
	adminToken string
}

// New builds the telemetry domain service.
func New(client telemetryservice.Service, adminToken string) *Service {
	return &Service{client: client, adminToken: adminToken}
}

// Backend returns the raw telemetry-service handle (module or gRPC mode).
// Used by pkg/server.go to mount the raw ingestion HTTP face
// (telemetry's pkg/ingesthttp), which speaks the downstream proto types
// directly and must not be adapted through testkit's mirrored messages.
func (s *Service) Backend() telemetryservice.Service { return s.client }

// adminCtx appends the admin Bearer token to the outgoing metadata.
func (s *Service) adminCtx(ctx context.Context) context.Context {
	if s.adminToken == "" {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+s.adminToken)
}
func (s *Service) Ingest(ctx context.Context, req *testkitv1.IngestRequest) (*testkitv1.IngestResponse, error) {
	resp, err := s.client.Ingest(ctx, toDnIngestRequest(req))
	if err != nil {
		return nil, err
	}
	return toTestkitIngestResponse(resp), nil
}

func (s *Service) CreateApp(ctx context.Context, req *testkitv1.CreateAppRequest) (*testkitv1.CreateAppResponse, error) {
	ctx = s.adminCtx(ctx)
	resp, err := s.client.CreateApp(ctx, toDnCreateAppRequest(req))
	if err != nil {
		return nil, err
	}
	return toTestkitCreateAppResponse(resp), nil
}

