func toDnApp(src *testkitv1.App) *dnv1.App {
	if src == nil {
		return nil
	}
	out := &dnv1.App{}
	out.Id = src.Id
	out.Slug = src.Slug
	out.Name = src.Name
	out.Email = src.Email
	out.StrictVersions = src.StrictVersions
	out.AuthMode = dnv1.AuthMode(src.AuthMode)
	out.AuthGraceUntil = src.AuthGraceUntil
	out.RatePerMinute = src.RatePerMinute
	out.RatePerDay = src.RatePerDay
	out.RawRetentionDays = src.RawRetentionDays
	out.DailyEventBudget = src.DailyEventBudget
	out.Disabled = src.Disabled
	out.CreatedAt = src.CreatedAt
	out.UpdatedAt = src.UpdatedAt
	return out
}

